package org.apache.dubbo.registry;

import org.apache.dubbo.common.URL;
import org.apache.dubbo.common.logger.ErrorTypeAwareLogger;
import org.apache.dubbo.common.logger.LoggerFactory;
import org.apache.dubbo.common.utils.CollectionUtils;
import org.apache.dubbo.common.utils.UrlUtils;

import java.util.List;
import java.util.function.Consumer;

import static org.apache.dubbo.common.constants.LoggerCodeConstants.INTERNAL_ERROR;

public class ListenerRegistryWrapper implements Registry {
    private static final ErrorTypeAwareLogger logger =
            LoggerFactory.getErrorTypeAwareLogger(ListenerRegistryWrapper.class);

    private final Registry registry;
    private final List<RegistryServiceListener> listeners;

    public ListenerRegistryWrapper(Registry registry, List<RegistryServiceListener> listeners) {
        this.registry = registry;
        this.listeners = listeners;
    }

    @Override
    public URL getUrl() {
        return registry.getUrl();
    }

    @Override
    public boolean isAvailable() {
        return registry.isAvailable();
    }

    @Override
    public void destroy() {
        registry.destroy();
    }

    @Override
    public void register(URL url) {
        registerAndNotify(url, () -> registry.register(url), serviceListener -> serviceListener.onRegister(url, registry));
    }

    @Override
    public void unregister(URL url) {
        registerAndNotify(
                url, () -> registry.unregister(url), serviceListener -> serviceListener.onUnregister(url, registry));
    }

    /**
     * Run the (un)register action against the delegate registry when present, then always notify the
     * provider-side listeners (skipped for consumer URLs), mirroring the register/unregister contract.
     */
    private void registerAndNotify(URL url, Runnable registryAction, Consumer<RegistryServiceListener> notification) {
        try {
            if (registry != null) {
                registryAction.run();
            }
        } finally {
            if (!UrlUtils.isConsumer(url)) {
                listenerEvent(notification);
            }
        }
    }

    @Override
    public void subscribe(URL url, NotifyListener listener) {
        try {
            if (registry != null) {
                registry.subscribe(url, listener);
            }
        } finally {
            listenerEvent(serviceListener -> serviceListener.onSubscribe(url, registry));
        }
    }

    @Override
    public void unsubscribe(URL url, NotifyListener listener) {
        try {
            registry.unsubscribe(url, listener);
        } finally {
            listenerEvent(serviceListener -> serviceListener.onUnsubscribe(url, registry));
        }
    }

    @Override
    public boolean isServiceDiscovery() {
        return registry.isServiceDiscovery();
    }

    @Override
    public List<URL> lookup(URL url) {
        return registry.lookup(url);
    }

    public Registry getRegistry() {
        return registry;
    }

    private void listenerEvent(Consumer<RegistryServiceListener> consumer) {
        if (CollectionUtils.isNotEmpty(listeners)) {
            RuntimeException exception = null;
            for (RegistryServiceListener listener : listeners) {
                if (listener != null) {
                    try {
                        consumer.accept(listener);
                    } catch (RuntimeException t) {
                        logger.error(INTERNAL_ERROR, "unknown error in registry module", "", t.getMessage(), t);
                        exception = t;
                    }
                }
            }
            if (exception != null) {
                throw exception;
            }
        }
    }
}

